#include "engine/replay.hpp"
#include <iomanip>
#include <locale>
#include <set>
#include <sstream>
#include <stdexcept>

namespace engine {
namespace {
constexpr std::size_t maxFrames=18001,maxSamples=180000,maxEvents=2048,maxBytes=64*1024*1024;
void text(std::string_view s,std::size_t limit,bool empty=false){if((!empty&&s.empty())||s.size()>limit)throw std::invalid_argument("Invalid replay text");for(unsigned char c:s)if(c<32||c==127)throw std::invalid_argument("Control character in replay text");}
void schema(const ReplayData& d){text(d.name,256);text(d.context,1024);if(d.poses.empty()||d.poses.size()>32||d.values.size()>16)throw std::invalid_argument("Replay channel budget exceeded");std::set<std::string> ids;for(const auto& id:d.poses){text(id,128);if(!ids.insert(id).second)throw std::invalid_argument("Duplicate replay pose channel");}ids.clear();for(const auto& id:d.values){text(id,128);if(!ids.insert(id).second)throw std::invalid_argument("Duplicate replay value channel");}}
void validPose(const JointPose& p){for(float v:{p.translation.x,p.translation.y,p.translation.z})if(!std::isfinite(v)||std::abs(v)>1000000)throw std::invalid_argument("Replay position out of range");for(float s:{p.scale.x,p.scale.y,p.scale.z})if(!std::isfinite(s)||s<.0001f||s>1000)throw std::invalid_argument("Replay scale out of range");const auto q=p.rotation;const double length=double(q.x)*q.x+double(q.y)*q.y+double(q.z)*q.z+double(q.w)*q.w;if(!std::isfinite(length)||std::abs(length-1)>.001)throw std::invalid_argument("Replay rotation must be normalized");p.matrix();}
void frame(const ReplayData& d,const ReplayFrame& f){if(!std::isfinite(f.time)||f.time<0||f.time>600||f.poses.size()!=d.poses.size()||f.values.size()!=d.values.size())throw std::invalid_argument("Invalid replay frame");for(const auto& p:f.poses)validPose(p);for(float v:f.values)if(!std::isfinite(v)||std::abs(v)>1e9f)throw std::invalid_argument("Invalid replay telemetry");}
void event(const ReplayEvent& e,double latest){if(!std::isfinite(e.time)||e.time<0||e.time>latest)throw std::invalid_argument("Replay event outside recorded time");text(e.name,128);text(e.payload,1024,true);}
}
JointPose replayPose(const Mat4& m){
    for(float v:m.m)if(!std::isfinite(v))throw std::invalid_argument("Non-finite replay matrix");
    if(std::abs(m.m[3])+std::abs(m.m[7])+std::abs(m.m[11])+std::abs(m.m[15]-1)>.0001f)throw std::invalid_argument("Replay matrix is not affine");
    Vec3 x{m.m[0],m.m[1],m.m[2]},y{m.m[4],m.m[5],m.m[6]},z{m.m[8],m.m[9],m.m[10]};
    JointPose p;p.translation={m.m[12],m.m[13],m.m[14]};p.scale={std::sqrt(dot(x,x)),std::sqrt(dot(y,y)),std::sqrt(dot(z,z))};
    if(std::min({p.scale.x,p.scale.y,p.scale.z})<.0001f)throw std::invalid_argument("Singular replay matrix");x=x*(1/p.scale.x);y=y*(1/p.scale.y);z=z*(1/p.scale.z);
    if(std::abs(dot(x,y))+std::abs(dot(y,z))+std::abs(dot(z,x))>.0001f||dot(x,cross(y,z))<.999f)throw std::invalid_argument("Replay requires positive TRS without shear");
    const float trace=x.x+y.y+z.z;
    if(trace>0){const float s=2*std::sqrt(trace+1);p.rotation={(y.z-z.y)/s,(z.x-x.z)/s,(x.y-y.x)/s,s/4};}
    else if(x.x>y.y&&x.x>z.z){const float s=2*std::sqrt(1+x.x-y.y-z.z);p.rotation={s/4,(y.x+x.y)/s,(z.x+x.z)/s,(y.z-z.y)/s};}
    else if(y.y>z.z){const float s=2*std::sqrt(1+y.y-x.x-z.z);p.rotation={(y.x+x.y)/s,s/4,(z.y+y.z)/s,(z.x-x.z)/s};}
    else{const float s=2*std::sqrt(1+z.z-x.x-y.y);p.rotation={(z.x+x.z)/s,(z.y+y.z)/s,s/4,(x.y-y.x)/s};}validPose(p);return p;
}
Transform replayTransform(const JointPose& p){validPose(p);const auto m=p.matrix();Transform t;t.position=p.translation;t.scale=p.scale;
    const float a=m.m[2]/p.scale.x;t.rotation.y=std::asin(std::clamp(-a,-1.f,1.f));
    if(std::abs(std::cos(t.rotation.y))>.00001f){t.rotation.x=std::atan2(m.m[6]/p.scale.y,m.m[10]/p.scale.z);t.rotation.z=std::atan2(m.m[1]/p.scale.x,m.m[0]/p.scale.x);}
    else{t.rotation.x=0;t.rotation.z=std::atan2(-m.m[4]/p.scale.y,m.m[5]/p.scale.y);}return t;
}
std::shared_ptr<const ReplayRecording> ReplayRecording::create(ReplayData d){schema(d);if(d.frames.size()<2||d.frames.size()>maxFrames||d.frames.size()*d.poses.size()>maxSamples||d.events.size()>maxEvents||d.frames.front().time!=0||d.frames.back().time<=0)throw std::invalid_argument("Invalid replay sample budget or duration");double previous=-1;for(const auto& f:d.frames){frame(d,f);if(f.time<=previous)throw std::invalid_argument("Replay frame times must increase");previous=f.time;}previous=-1;for(const auto& e:d.events){event(e,d.frames.back().time);if(e.time<previous)throw std::invalid_argument("Replay events must be ordered");previous=e.time;}return std::shared_ptr<const ReplayRecording>(new ReplayRecording(std::move(d)));}
ReplayFrame ReplayRecording::sample(double time)const{if(!std::isfinite(time)||time<0||time>duration())throw std::invalid_argument("Replay sample outside duration");const auto next=std::upper_bound(data_.frames.begin(),data_.frames.end(),time,[](double t,const auto& f){return t<f.time;});if(next==data_.frames.end())return data_.frames.back();const auto& a=*(next-1);const auto& b=*next;ReplayFrame out=a;out.time=time;if(b.cut)return out;const float w=float((time-a.time)/(b.time-a.time));for(std::size_t i=0;i<out.poses.size();++i)out.poses[i]=blendPose(a.poses[i],b.poses[i],w);for(std::size_t i=0;i<out.values.size();++i)out.values[i]=a.values[i]*(1-w)+b.values[i]*w;return out;}
std::span<const ReplayEvent> ReplayRecording::eventsBetween(double begin,double end)const{if(!std::isfinite(begin)||!std::isfinite(end)||begin<0||end<begin||end>duration())throw std::invalid_argument("Invalid replay event range");const auto upper=[&](double t){return std::upper_bound(data_.events.begin(),data_.events.end(),t,[](double t,const auto& e){return t<e.time;});};const auto a=upper(begin),b=upper(end);return {a,std::size_t(b-a)};}
ReplayRecorder::ReplayRecorder(ReplayData d):data_(std::move(d)){schema(data_);if(!data_.frames.empty()||!data_.events.empty())throw std::invalid_argument("Recorder requires empty schema");}
bool ReplayRecorder::capture(ReplayFrame f){frame(data_,f);if((data_.frames.empty()&&f.time!=0)||(!data_.frames.empty()&&f.time<=data_.frames.back().time))throw std::invalid_argument("Invalid replay capture order");if(data_.frames.size()>=maxFrames||(data_.frames.size()+1)*data_.poses.size()>maxSamples)return false;data_.frames.push_back(std::move(f));return true;}
bool ReplayRecorder::event(ReplayEvent e){engine::event(e,data_.frames.empty()?-1:data_.frames.back().time);if(!data_.events.empty()&&e.time<data_.events.back().time)throw std::invalid_argument("Replay events must be ordered");if(data_.events.size()>=maxEvents)return false;data_.events.push_back(std::move(e));return true;}
std::shared_ptr<const ReplayRecording> ReplayRecorder::finish()const{return ReplayRecording::create(data_);}
std::string ReplayArchive::save(const ReplayRecording& r){const auto& d=r.data();std::ostringstream o;o.imbue(std::locale::classic());o<<std::setprecision(17)<<"WEGHOST 1\n"<<std::quoted(d.name)<<' '<<std::quoted(d.context)<<' '<<d.poses.size()<<' '<<d.values.size()<<' '<<d.frames.size()<<' '<<d.events.size()<<'\n';for(const auto& s:d.poses)o<<std::quoted(s)<<'\n';for(const auto& s:d.values)o<<std::quoted(s)<<'\n';for(const auto& f:d.frames){o<<f.time<<' '<<f.cut;for(const auto& p:f.poses)o<<' '<<p.translation.x<<' '<<p.translation.y<<' '<<p.translation.z<<' '<<p.scale.x<<' '<<p.scale.y<<' '<<p.scale.z<<' '<<p.rotation.x<<' '<<p.rotation.y<<' '<<p.rotation.z<<' '<<p.rotation.w;for(float v:f.values)o<<' '<<v;o<<'\n';}for(const auto& e:d.events)o<<e.time<<' '<<std::quoted(e.name)<<' '<<std::quoted(e.payload)<<'\n';auto s=o.str();if(s.size()>maxBytes)throw std::invalid_argument("Replay file exceeds 64 MiB");return s;}
std::shared_ptr<const ReplayRecording> ReplayArchive::load(std::string_view source){if(source.empty()||source.size()>maxBytes)throw std::invalid_argument("Invalid replay file size");std::istringstream in{std::string(source)};in.imbue(std::locale::classic());std::string magic;int version;std::size_t np,nv,nf,ne;ReplayData d;if(!(in>>magic>>version>>std::quoted(d.name)>>std::quoted(d.context)>>np>>nv>>nf>>ne)||magic!="WEGHOST"||version!=1||np<1||np>32||nv>16||nf<2||nf>maxFrames||nf*np>maxSamples||ne>maxEvents)throw std::invalid_argument("Invalid replay header");for(std::size_t i=0;i<np+nv;++i){std::string s;if(!(in>>std::quoted(s)))throw std::invalid_argument("Invalid replay channel");(i<np?d.poses:d.values).push_back(std::move(s));}schema(d);for(std::size_t i=0;i<nf;++i){ReplayFrame f;if(!(in>>f.time>>f.cut))throw std::invalid_argument("Invalid replay frame");for(std::size_t j=0;j<np;++j){JointPose p;if(!(in>>p.translation.x>>p.translation.y>>p.translation.z>>p.scale.x>>p.scale.y>>p.scale.z>>p.rotation.x>>p.rotation.y>>p.rotation.z>>p.rotation.w))throw std::invalid_argument("Invalid replay pose");f.poses.push_back(p);}for(std::size_t j=0;j<nv;++j){float v;if(!(in>>v))throw std::invalid_argument("Invalid replay value");f.values.push_back(v);}frame(d,f);d.frames.push_back(std::move(f));}for(std::size_t i=0;i<ne;++i){ReplayEvent e;if(!(in>>e.time>>std::quoted(e.name)>>std::quoted(e.payload)))throw std::invalid_argument("Invalid replay event");event(e,d.frames.back().time);d.events.push_back(std::move(e));}in>>std::ws;if(!in.eof())throw std::invalid_argument("Trailing replay data");return ReplayRecording::create(std::move(d));}
ReplayPlayer::ReplayPlayer(std::shared_ptr<const ReplayRecording> r):recording_(std::move(r)){if(!recording_)throw std::invalid_argument("Missing replay recording");}
void ReplayPlayer::seek(double t){if(!std::isfinite(t)||t<0||t>recording_->duration())throw std::invalid_argument("Replay seek outside duration");time_=t;playing_=false;}
void ReplayPlayer::play(){if(time_>=recording_->duration())time_=0;playing_=true;}
void ReplayPlayer::setSpeed(float speed){if(!std::isfinite(speed)||speed<.125f||speed>4)throw std::invalid_argument("Replay speed must be .125..4");speed_=speed;}
void ReplayPlayer::advance(double dt){if(!std::isfinite(dt)||dt<0||dt>.25)throw std::invalid_argument("Replay delta must be 0..0.25 seconds");if(!playing_)return;const double next=time_+dt*speed_;if(next>=recording_->duration()){if(looping)time_=std::fmod(next,recording_->duration());else{time_=recording_->duration();playing_=false;}}else time_=next;}
}
